<script lang="ts">
  import type { Json, WorkspaceDocument, WorkspaceSnapshot } from '../types';
  import { array, documentTitle, documentsOf, isLocked, netNodes, pairList, parseScalar, scalar, tags, type NetNodeView } from '../workspace';
  let { workspace, onChanged, focusName='' }: {workspace:WorkspaceSnapshot;onChanged:()=>void;focusName?:string}=$props();
  let documentList=$derived(documentsOf(workspace,['network','region']));
  let nodeListsByDocument=$derived(new Map(documentList.map(document=>[document.id,netNodes(document)])));
  let selectedDoc=$state(0);let focusApplied=$state(false);let selectedNode=$state('');let dragIndex=$state<number|null>(null);let panPointer=$state<number|null>(null);let panClientX=$state(0);let panClientY=$state(0);let viewX=$state(0);let viewY=$state(0);let viewWidth=$state(1000);let viewHeight=$state(660);let newTag=$state('');let tagError=$state('');
  let currentDocument=$derived(documentList[Math.min(selectedDoc,Math.max(0,documentList.length-1))]);
  let nodeList=$derived(currentDocument?nodeListsByDocument.get(currentDocument.id)??[]:[]);
  let spatialNodes=$derived(nodeList.filter(n=>n.spatial&&n.position.length>=3));
  let spatialByIndex=$derived(new Map(spatialNodes.map(n=>[n.index,n])));
  let selectedNodeView=$derived(nodeList.find(n=>n.key===selectedNode)??spatialNodes[0]);
  let graphBounds=$derived.by(()=>{const xs=spatialNodes.map(n=>Number(n.position[0])||0),zs=spatialNodes.map(n=>Number(n.position[2])||0);let minX=Math.min(...xs,0),maxX=Math.max(...xs,1),minZ=Math.min(...zs,0),maxZ=Math.max(...zs,1);if(maxX-minX<10){minX-=5;maxX+=5}if(maxZ-minZ<10){minZ-=5;maxZ+=5}return{minX,maxX,minZ,maxZ,sx:900/(maxX-minX),sz:560/(maxZ-minZ)}});
  let regionCycleNodes=$derived.by(()=>{if(currentDocument?.kind!=='region'||spatialNodes.length<3)return[];if(spatialNodes.some(n=>n.links.filter(x=>typeof x==='number'&&spatialByIndex.has(Number(x))).length!==2))return[];const ordered=[spatialNodes[0]],visited=new Set([spatialNodes[0].index]);let previous=-1,current=spatialNodes[0];while(ordered.length<=spatialNodes.length){const choices=current.links.map(Number).filter(i=>spatialByIndex.has(i)&&i!==previous);const next=spatialByIndex.get(choices[0]);if(!next)return[];if(next.index===ordered[0].index)return ordered.length===spatialNodes.length?ordered:[];if(visited.has(next.index))return[];ordered.push(next);visited.add(next.index);previous=current.index;current=next}return[]});
  $effect(()=>{if(!focusApplied&&documentList.length){selectedDoc=Math.max(0,documentList.findIndex(d=>documentTitle(d).toLowerCase()===focusName.toLowerCase()));focusApplied=true}});
  function doc():WorkspaceDocument|undefined{return currentDocument}
  function point(position:Json[]){const b=graphBounds;return{x:50+(Number(position[0])-b.minX)*b.sx,y:50+(Number(position[2])-b.minZ)*b.sz}}
  function world(x:number,y:number){const b=graphBounds;return{x:b.minX+(x-50)/b.sx,z:b.minZ+(y-50)/b.sz}}
  function viewPoint(event:PointerEvent|WheelEvent,svg:SVGSVGElement){const rect=svg.getBoundingClientRect();return{x:viewX+(event.clientX-rect.left)*viewWidth/rect.width,y:viewY+(event.clientY-rect.top)*viewHeight/rect.height}}
  function screenScale(){return viewWidth/1000}
  function directedEnd(from:{x:number;y:number},to:{x:number;y:number}){const dx=to.x-from.x,dy=to.y-from.y,length=Math.hypot(dx,dy)||1,padding=13*screenScale();return{x:to.x-dx/length*padding,y:to.y-dy/length*padding,angle:Math.atan2(dy,dx)*180/Math.PI}}
  function resetView(){viewX=0;viewY=0;viewWidth=1000;viewHeight=660}
  function zoomAt(factor:number,x=viewX+viewWidth/2,y=viewY+viewHeight/2){const nextWidth=Math.min(4000,Math.max(10,viewWidth*factor));const nextHeight=nextWidth*.66;const ratioX=(x-viewX)/viewWidth,ratioY=(y-viewY)/viewHeight;viewX=x-ratioX*nextWidth;viewY=y-ratioY*nextHeight;viewWidth=nextWidth;viewHeight=nextHeight}
  function wheelZoom(event:WheelEvent){event.preventDefault();const svg=event.currentTarget as SVGSVGElement;const p=viewPoint(event,svg);zoomAt(event.deltaY<0?.82:1.22,p.x,p.y)}
  function edgeTarget(index:number){return spatialByIndex.get(index)}
  function setPosition(node:NetNodeView,index:number,text:string){node.position[index]=parseScalar(text,node.position[index]);node.record[1]=node.position;onChanged()}
  function setLinks(node:NetNodeView,text:string){node.links=text.split(',').map(x=>x.trim()).filter(Boolean).map(Number).filter(Number.isFinite);node.record[2]=node.links;onChanged()}
  function setSpecialEndpoint(node:NetNodeView,index:number,text:string){if(!node.specialEdge)return;const value=Number(text);if(!Number.isFinite(value))return;node.specialEdge[index]=value;node.record[0]=node.specialEdge;onChanged()}
  function setTag(node:NetNodeView,at:number,text:string){try{node.record[at+1]=JSON.parse(text);tagError='';onChanged()}catch(error){tagError=`Invalid JSON for ${node.record[at]}: ${String(error)}`}}
  function tagHint(tag:string,value:Json):string{if(!Array.isArray(value))return'';if(tag==='valve'&&typeof value[0]==='number'&&typeof value[1]==='string'){if(typeof value[2]==='number')return`Enabled state condition: ${value[1]} must equal ${value[2]}; leading ${value[0]} is the enable flag.`;return`Enabled state condition for ${value[1]}; no explicit target value, so the engine derives it from the outgoing-connection index. Leading ${value[0]} is the enable flag.`}if(tag==='valveunion'){return`OR of enabled state conditions; each member is [enable flag, channel name, target value].`}if(['speed','canleave','scan_aim','scan_hit','scan_time','jump','wait_interval','wait_time'].includes(tag)&&typeof value[0]==='number'){return`Leading ${value[0]} is the enable flag; the following value is this tag's parameter.`}if(tag==='valve_assign'&&typeof value[0]==='string')return`State assignment on this connection: set ${value[0]} = ${scalar(value[1])}.`;if(tag==='gate'&&typeof value[0]==='string')return`Vehicle gate associated with ${value[0]} on this connection.`;return''}
  function addTag(node:NetNodeView){const name=newTag.trim();if(!name)return;node.record.push(name,[]);newTag='';tagError='';onChanged()}
  function removeTag(node:NetNodeView,at:number){node.record.splice(at,2);tagError='';onChanged()}
  function addNode(){const d=doc();if(!d)return;const index=Math.max(-1,...nodeList.map(n=>n.index))+1;const b=graphBounds;pairList(d.root).push(`node_${String(index).padStart(2,'0')}`,[12,[(b.minX+b.maxX)/2,0,(b.minZ+b.maxZ)/2],[]]);selectedNode=`node_${String(index).padStart(2,'0')}`;onChanged()}
  function removeNode(node:NetNodeView){const d=doc();if(!d)return;const root=pairList(d.root);for(const other of netNodes(d).filter(n=>!n.spatial&&n.specialEdge?.some(x=>Number(x)===node.index)).sort((a,b)=>b.pairIndex-a.pairIndex))root.splice(other.pairIndex,2);for(const other of netNodes(d)){if(other.spatial){other.links=other.links.filter(x=>Number(x)!==node.index);other.record[2]=other.links}}for(let i=0;i+1<root.length;i+=2){if(root[i]===node.key){root.splice(i,2);break}}selectedNode='';onChanged()}
  function pointerDown(event:PointerEvent,node:NetNodeView){event.stopPropagation();if(!doc()||isLocked(workspace,doc()!))return;dragIndex=node.index;selectedNode=node.key;(event.currentTarget as SVGGElement).setPointerCapture(event.pointerId)}
  function selectSpecial(event:PointerEvent,node:NetNodeView){event.stopPropagation();selectedNode=node.key}
  function panDown(event:PointerEvent){if(event.button!==0&&event.button!==1)return;panPointer=event.pointerId;panClientX=event.clientX;panClientY=event.clientY;(event.currentTarget as SVGSVGElement).setPointerCapture(event.pointerId)}
  function pointerMove(event:PointerEvent){const svg=event.currentTarget as SVGSVGElement;if(dragIndex!==null){const p=viewPoint(event,svg);const position=world(p.x,p.y);const node=spatialByIndex.get(dragIndex);if(node){node.position[0]=position.x;node.position[2]=position.z;node.record[1]=node.position;onChanged()}return}if(panPointer===event.pointerId){const rect=svg.getBoundingClientRect();viewX-=(event.clientX-panClientX)*viewWidth/rect.width;viewY-=(event.clientY-panClientY)*viewHeight/rect.height;panClientX=event.clientX;panClientY=event.clientY}}
  function pointerUp(event:PointerEvent){if(panPointer===event.pointerId)panPointer=null;dragIndex=null}
</script>

<div class="editor-shell network-shell">
  <aside class="object-sidebar">
    <div class="side-heading"><div><small>ZRdrAiNet</small><b>Networks & Regions</b></div></div>
    <div class="section-label">Mission layer</div><div class="object-list compact">{#each documentList as item,i (item.id)}<button class:active={i===selectedDoc} onclick={()=>{selectedDoc=i;selectedNode=''}}><span><b>{documentTitle(item)}</b><small>{item.kind} · {item.layer}</small></span><small>{nodeListsByDocument.get(item.id)?.length??0}</small></button>{/each}</div>
  </aside>
  <section class="network-workspace">
    {#if currentDocument}{@const currentDoc=currentDocument}{@const currentNode=selectedNodeView}
      {#if isLocked(workspace,currentDoc)}<div class="locked-banner">{currentDoc.entryName} is in a locked {currentDoc.layer} Reader.</div>{/if}
      <div class="network-toolbar"><div><small>{currentDoc.kind.toUpperCase()}</small><h2>{documentTitle(currentDoc)}</h2></div><div><span>{spatialNodes.length} spatial nodes</span><div class="zoom-controls"><button title="Zoom out" onclick={()=>zoomAt(1.22)}>−</button><span>{Math.round(1000/viewWidth*100)}%</span><button title="Zoom in" onclick={()=>zoomAt(.82)}>+</button><button title="Fit graph" onclick={resetView}>Fit</button></div><button disabled={isLocked(workspace,currentDoc)} onclick={addNode}>Add node</button></div></div>
      <div class="network-layout">
        <div class="viewport-card">
          <svg class:panning={panPointer!==null} class="network-viewport" viewBox={`${viewX} ${viewY} ${viewWidth} ${viewHeight}`} role="application" aria-label="AI network and region graph. Use the mouse wheel to zoom and drag empty space to pan." onwheel={wheelZoom} onpointerdown={panDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={pointerUp}>
            <defs><pattern id="minor-grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M 25 0 L 0 0 0 25" fill="none" stroke="#1b2a30" stroke-width="1"/></pattern><pattern id="major-grid" width="100" height="100" patternUnits="userSpaceOnUse"><rect width="100" height="100" fill="url(#minor-grid)"/><path d="M 100 0 L 0 0 0 100" fill="none" stroke="#2b3b42" stroke-width="1"/></pattern></defs>
            <rect width="1000" height="660" fill="#091115"/><rect width="1000" height="660" fill="url(#major-grid)"/>
            {#if regionCycleNodes.length}{@const polygon=regionCycleNodes.map(n=>{const p=point(n.position);return`${p.x},${p.y}`}).join(' ')}<polygon points={polygon} fill="#d85e2d22" stroke="#e16a3b" stroke-width="2" vector-effect="non-scaling-stroke"/>{/if}
            {#each spatialNodes as source}{@const a=point(source.position)}{#each source.links.map(Number) as targetIndex}{@const target=edgeTarget(targetIndex)}{#if target}{@const b=point(target.position)}{@const end=directedEnd(a,b)}<line x1={a.x} y1={a.y} x2={end.x} y2={end.y} class="net-edge"><title>{source.key} → node_{String(targetIndex).padStart(2,'0')}</title></line><g class="connection-arrow" transform={`translate(${end.x} ${end.y}) rotate(${end.angle}) scale(${screenScale()})`}><path d="M 0 0 L -8 -4 L -8 4 Z"/></g>{/if}{/each}{/each}
            {#each nodeList.filter(n=>n.specialEdge?.length) as special}{@const from=edgeTarget(Number(special.specialEdge![0]))}{@const to=edgeTarget(Number(special.specialEdge![1]))}{#if from&&to}{@const a=point(from.position)}{@const b=point(to.position)}<line x1={a.x} y1={a.y} x2={b.x} y2={b.y} class="special-edge"/><g transform={`translate(${(a.x+b.x)/2} ${(a.y+b.y)/2}) scale(${screenScale()})`} role="button" tabindex="0" class:selected-edge={currentNode?.key===special.key} aria-label={`Select edge rule ${special.key}`} onpointerdown={e=>selectSpecial(e,special)} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectedNode=special.key}}}><rect x="-27" y="-10" width="54" height="20" rx="4" class="edge-badge"/><text text-anchor="middle" dominant-baseline="middle">{tags(special.record,special.tagStart)[0]?.tag??'edge rule'}</text></g>{/if}{/each}
            {#each spatialNodes as node (node.id)}{@const p=point(node.position)}<g transform={`translate(${p.x} ${p.y}) scale(${screenScale()})`} role="button" tabindex="0" aria-label={`Select and move ${node.key}`} class:tagged-node={tags(node.record,node.tagStart).length>0} class:selected-node={currentNode?.key===node.key} onclick={()=>selectedNode=node.key} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectedNode=node.key}}} onpointerdown={e=>pointerDown(e,node)}><circle cx="0" cy="0" r="9"/><text x="13" y="-11">{node.key}</text></g>{/each}
          </svg>
          <div class="map-hint">Arrows: directed connections · purple: tagged nodes · orange: edge rules · wheel: zoom · drag background: pan</div>
        </div>
        <aside class="property-panel">
          {#if currentNode}<fieldset disabled={isLocked(workspace,currentDoc)} class="editor-fields"><div class="property-title"><div><small>{currentNode.spatial?'SPATIAL NODE':'EDGE RULE RECORD'}</small><h3>{currentNode.key}</h3></div><button class="danger" onclick={()=>removeNode(currentNode)}>Delete</button></div>
            {#if currentNode.spatial}<div class="property-section"><h4>Position</h4>{#each ['X','Y','Z'] as axis,i}<label><span class="field-title">{axis} <small>(record[1][{i}])</small></span><input type="number" step="any" value={scalar(currentNode.position[i])} oninput={e=>setPosition(currentNode,i,e.currentTarget.value)}></label>{/each}</div><div class="property-section"><h4>Connections</h4><label><span class="field-title">Directed target node indices <small>(record[2])</small></span><input value={currentNode.links.join(', ')} onchange={e=>setLinks(currentNode,e.currentTarget.value)}></label><p>Serialized order is preserved. Multiple values are outgoing candidates; edge rules may qualify individual paths.</p></div>{/if}
            {#if !currentNode.spatial&&currentNode.specialEdge}<div class="property-section"><h4>Applies to directed connection</h4><label><span class="field-title">From node <small>(record[0][0])</small></span><input type="number" value={scalar(currentNode.specialEdge[0])} onchange={e=>setSpecialEndpoint(currentNode,0,e.currentTarget.value)}></label><label><span class="field-title">To node <small>(record[0][1])</small></span><input type="number" value={scalar(currentNode.specialEdge[1])} onchange={e=>setSpecialEndpoint(currentNode,1,e.currentTarget.value)}></label><p>This record has no map position. Its tags modify the connection above.</p></div>{/if}
            <div class="property-section"><h4>{currentNode.spatial?'Optional node tags':'Edge rules'}</h4>{#each tags(currentNode.record,currentNode.tagStart) as tag}<label><span class="field-title">{tag.tag} <small>(record[{tag.at}])</small><button type="button" class="inline-danger" onclick={()=>removeTag(currentNode,tag.at)}>Remove</button></span><textarea class="json-value" onchange={e=>setTag(currentNode,tag.at,e.currentTarget.value)}>{JSON.stringify(tag.value)}</textarea>{#if tagHint(tag.tag,tag.value)}<small class="tag-hint">{tagHint(tag.tag,tag.value)}</small>{/if}</label>{/each}{#if !tags(currentNode.record,currentNode.tagStart).length}<p>No optional tags.</p>{/if}<div class="inline-editor"><input placeholder="Tag name, e.g. valve" bind:value={newTag}><button type="button" disabled={!newTag.trim()} onclick={()=>addTag(currentNode)}>Add tag</button></div>{#if tagError}<p class="field-error">{tagError}</p>{/if}</div>
            <details><summary>Raw node</summary><pre>{JSON.stringify(currentNode.record,null,2)}</pre></details>
          </fieldset>{:else}<div class="empty">Select a spatial or special node.</div>{/if}
        </aside>
      </div>
    {:else}<div class="empty-state"><h2>No networks or regions loaded</h2><p>The selected Reader layers contain no `net_*.zrd` or `reg_*.zrd` documents.</p></div>{/if}
  </section>
</div>
